; cart32.asm -- chapter 15: a cartridge of 32 KB
; generated by gen15.py
        INCLUDE "msx.inc"
        OUTPUT "cart32.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; A cartridge of 32 KB: the second 16 KB is for page 2, $8000-$BFFF. At
; INIT the BIOS has switched page 1 to the cartridge, and only page 1
; (chapter 3): the program reads the first byte of its second half.
init:   di
        ld sp, SYS_AREA
        ld a, (second)          ; the first byte of the second half ...
        ld (RESULTS), a         ; ... as the processor finds it
        VDP_REG 7, LIGHT_GREEN
stop:   jr stop
        ASSERT $ <= $8000, the first half is full
        ds $8000 - $, $FF       ; the first 16 KB
second: db "The second half."
        ASSERT $ <= $C000, the program is longer than the cartridge
        ds $C000 - $, $FF       ; the second 16 KB
